INSERT INTO public.careers (slug, title, category, overview, skills, salary, demand, future_scope, growth, roadmap, top_companies, courses, certifications, eligibility, match_tags) VALUES ('ai-engineer', 'AI Engineer', 'AI & Machine Learning', 'AI Engineers build intelligent systems that can learn, reason, and make decisions. They work on machine learning models, neural networks, and natural language processing.', '["Python","TensorFlow","PyTorch","Deep Learning","NLP","Mathematics","Statistics"]'::jsonb, '₹6–40 LPA', 'Very High', 'AI is reshaping every industry. Demand will grow 10x by 2030 with applications in healthcare, finance, autonomous vehicles, and more.', '35% annual growth', '[{"phase":"Foundation (3-6 months)","items":["Python programming","Linear Algebra & Statistics","Data structures & algorithms"]},{"phase":"Core ML (6-12 months)","items":["Scikit-learn","Supervised & unsupervised learning","Model evaluation & tuning"]},{"phase":"Deep Learning (6-12 months)","items":["Neural networks","TensorFlow/Keras","CNNs and RNNs"]},{"phase":"Specialization (ongoing)","items":["NLP or Computer Vision","MLOps","Deploy models with Docker/Kubernetes"]}]'::jsonb, '["Google","Microsoft","OpenAI","Amazon","Meta","Nvidia"]'::jsonb, '["ML Specialization — Coursera","Deep Learning — NPTEL","AI for Everyone — SWAYAM"]'::jsonb, '["TensorFlow Developer Certificate","AWS ML Specialty","Google Professional ML Engineer"]'::jsonb, 'B.Tech / B.Sc / MCA / Any graduate with strong math', '["programming","math","analytical","logical","research"]'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.careers (slug, title, category, overview, skills, salary, demand, future_scope, growth, roadmap, top_companies, courses, certifications, eligibility, match_tags) VALUES ('data-scientist', 'Data Scientist', 'Data & Analytics', 'Data Scientists extract insights from large datasets using statistical analysis, machine learning, and data visualization to drive business decisions.', '["Python","R","SQL","Statistics","Pandas","Tableau","Machine Learning"]'::jsonb, '₹5–35 LPA', 'Very High', 'Data-driven decision making is becoming universal. Every company needs data scientists to stay competitive.', '28% annual growth', '[{"phase":"Foundation (2-4 months)","items":["Python & SQL","Statistics & probability","Excel proficiency"]},{"phase":"Data Tools (3-6 months)","items":["Pandas & NumPy","Data visualization (Matplotlib, Seaborn)","Tableau / Power BI"]},{"phase":"Machine Learning (4-8 months)","items":["Supervised learning","Model deployment","Big data basics (Spark)"]},{"phase":"Advanced (ongoing)","items":["Deep learning","NLP","Cloud platforms (AWS/GCP)"]}]'::jsonb, '["Amazon","Flipkart","Mu Sigma","Fractal","Deloitte"]'::jsonb, '["Data Science Bootcamp — Coursera","PG Program — UpGrad","Data Science — NPTEL"]'::jsonb, '["IBM Data Science Professional","SAS Certified Data Scientist","Microsoft Azure Data Scientist"]'::jsonb, 'B.Tech / B.Sc Statistics / M.Sc / Any graduate', '["math","analytical","research","logical","programming"]'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.careers (slug, title, category, overview, skills, salary, demand, future_scope, growth, roadmap, top_companies, courses, certifications, eligibility, match_tags) VALUES ('fullstack-developer', 'Full Stack Developer', 'Software Development', 'Full Stack Developers build end-to-end web applications, working on both frontend (React, Angular) and backend (Node.js, Python, Java) with databases.', '["JavaScript","React","Node.js","HTML/CSS","SQL","Git","REST APIs"]'::jsonb, '₹4–25 LPA', 'Very High', 'Web development continues to be the backbone of the digital economy. Full stack skills remain in top demand across startups and enterprises.', '22% annual growth', '[{"phase":"Frontend (3-5 months)","items":["HTML, CSS, JavaScript","React.js","Responsive design"]},{"phase":"Backend (4-6 months)","items":["Node.js / Express","Databases (MongoDB, PostgreSQL)","REST API design"]},{"phase":"DevOps (2-4 months)","items":["Git & GitHub","Docker","CI/CD basics"]},{"phase":"Projects (ongoing)","items":["Build full-stack apps","Deploy to cloud","Open source contributions"]}]'::jsonb, '["TCS","Infosys","Razorpay","Swiggy","Zomato"]'::jsonb, '["Full Stack — The Odin Project","MERN Stack — Coursera","Web Dev — Udemy"]'::jsonb, '["Meta Front-End Developer","FreeCodeCamp certifications","AWS Developer Associate"]'::jsonb, 'B.Tech CS / BCA / MCA / Any graduate', '["programming","logical","creative","technical","analytical"]'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.careers (slug, title, category, overview, skills, salary, demand, future_scope, growth, roadmap, top_companies, courses, certifications, eligibility, match_tags) VALUES ('cyber-security-analyst', 'Cyber Security Analyst', 'Cyber Security', 'Cyber Security Analysts protect organizations from digital threats by monitoring systems, analyzing vulnerabilities, and implementing security measures.', '["Networking","Linux","Penetration Testing","Cryptography","SIEM","Python"]'::jsonb, '₹5–30 LPA', 'Very High', 'With rising cyber threats and digital transformation, cyber security is one of the fastest-growing fields globally.', '32% annual growth', '[{"phase":"Foundation (3-6 months)","items":["Networking fundamentals","Linux & command line","Operating systems"]},{"phase":"Security Basics (4-6 months)","items":["Cryptography","Web security (OWASP)","Security tools (Nmap, Wireshark)"]},{"phase":"Advanced (6-12 months)","items":["Penetration testing","SIEM tools","Incident response"]},{"phase":"Specialization (ongoing)","items":["Cloud security","Malware analysis","Bug bounty hunting"]}]'::jsonb, '["TCS","Wipro","Deloitte","KPMG","Quick Heal"]'::jsonb, '["Cybersecurity — Coursera","Ethical Hacking — Udemy","Security+ — CompTIA"]'::jsonb, '["CEH (Certified Ethical Hacker)","CompTIA Security+","CISSP","OSCP"]'::jsonb, 'B.Tech IT / B.Sc CS / Any graduate', '["logical","analytical","technical","problem-solving","research"]'::jsonb) ON CONFLICT (slug) DO NOTHING;
