INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-1', 'programming', 'Beginner', 'Which of the following is NOT a primitive data type in JavaScript?', '["String","Number","Array","Boolean"]'::jsonb, 2, 'Array is a reference type (object) in JavaScript, not a primitive. Primitives include: String, Number, Boolean, null, undefined, Symbol, and BigInt.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-2', 'programming', 'Beginner', 'In Python, indentation is used to define code blocks.', '["True","False"]'::jsonb, 0, 'Python uses indentation (whitespace) to define blocks of code, unlike most other languages that use braces {}.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-3', 'programming', 'Intermediate', 'What is the output of the following Python code?
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-4', 'programming', 'Intermediate', 'What is the time complexity of binary search?', '["O(n)","O(log n)","O(n²)","O(1)"]'::jsonb, 1, 'Binary search halves the search space at each step, giving it O(log n) time complexity. It requires the data to be sorted.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-5', 'programming', 'Advanced', 'You need to find if two strings are anagrams. Which approach is most efficient?', '["Sort both strings and compare — O(n log n)","Count character frequencies using a hash map — O(n)","Check all permutations of one string — O(n!)","Use nested loops to compare characters — O(n²)"]'::jsonb, 1, 'Using a hash map (dictionary) to count character frequencies is O(n) time and O(1) space (since only 26 letters). Sorting is O(n log n) and also valid but less optimal.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-6', 'programming', 'Beginner', 'In Python, the keyword used to define a function is ___.', '["function","def","func","define"]'::jsonb, 1, 'The "def" keyword is used to define functions in Python. Example: def my_function():') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-7', 'programming', 'Intermediate', 'What does OOP stand for in software development?', '["Open Operational Programming","Object Oriented Programming","Output Oriented Processing","Ordered Object Protocol"]'::jsonb, 1, 'OOP stands for Object-Oriented Programming — a paradigm based on the concept of objects that contain data (attributes) and code (methods).') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('prog-8', 'programming', 'Advanced', 'What does this JavaScript code output?
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('aiml-1', 'ai-ml', 'Beginner', 'Which of the following is a supervised learning algorithm?', '["K-Means Clustering","Principal Component Analysis","Linear Regression","DBSCAN"]'::jsonb, 2, 'Linear Regression is a supervised learning algorithm — it learns from labeled training data. K-Means, PCA, and DBSCAN are unsupervised methods.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('aiml-2', 'ai-ml', 'Beginner', 'Overfitting occurs when a model performs well on training data but poorly on test data.', '["True","False"]'::jsonb, 0, 'Overfitting means the model memorizes training data including noise, losing its ability to generalize to unseen data. Solutions include regularization, dropout, and more data.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('aiml-3', 'ai-ml', 'Intermediate', 'What activation function is commonly used in the output layer for binary classification?', '["ReLU","Softmax","Sigmoid","Tanh"]'::jsonb, 2, 'Sigmoid outputs a value between 0 and 1, making it ideal for binary classification. Softmax is used for multi-class classification (output layer).') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('aiml-4', 'ai-ml', 'Advanced', 'What is the "vanishing gradient problem" in deep neural networks?', '["Gradients become too large during backpropagation","Gradients become very small, slowing or stopping learning in early layers","The loss function reaches zero too quickly","The network loses input data during forward pass"]'::jsonb, 1, 'In deep networks, gradients can shrink exponentially as they propagate backward through many layers, making early layers learn very slowly. Solutions: ReLU activation, batch normalization, residual connections.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('aiml-5', 'ai-ml', 'Intermediate', 'Your ML model achieves 99% accuracy but the dataset is 99% class A and 1% class B. This is an example of:', '["Excellent model performance","Class imbalance problem","Overfitting","High variance"]'::jsonb, 1, 'A model that always predicts the majority class gets 99% accuracy on imbalanced data without learning anything useful. Use metrics like F1-score, precision, recall, or ROC-AUC instead.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('ds-1', 'data-science', 'Beginner', 'Which Pandas method is used to display the first 5 rows of a DataFrame?', '["df.tail()","df.head()","df.first()","df.show()"]'::jsonb, 1, 'df.head() returns the first n rows (default 5). df.tail() returns the last n rows. These are essential for quick data inspection.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('ds-2', 'data-science', 'Intermediate', 'What is the purpose of feature scaling in machine learning?', '["To increase the number of features","To normalize feature values to a similar range, improving model convergence","To remove outliers from the dataset","To encode categorical variables"]'::jsonb, 1, 'Feature scaling ensures all features contribute equally to the model. Without it, features with large values can dominate. Methods include Min-Max scaling and Standardization (Z-score).') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('ds-3', 'data-science', 'Beginner', 'Missing values in a dataset should always be deleted.', '["True","False"]'::jsonb, 1, 'Deleting rows with missing values can lose important information. Better strategies include imputation (mean, median, mode), forward/backward fill, or using algorithms that handle missing data natively.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('web-1', 'web-development', 'Beginner', 'What does CSS stand for?', '["Computer Style Sheets","Creative Style System","Cascading Style Sheets","Colorful Style Sheets"]'::jsonb, 2, 'CSS stands for Cascading Style Sheets. It is used to style and layout HTML elements on a web page.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('web-2', 'web-development', 'Intermediate', 'What is the virtual DOM in React?', '["A real browser DOM stored on the server","A lightweight JavaScript representation of the real DOM used for efficient updates","A CSS framework for styling React components","A database for storing React component state"]'::jsonb, 1, 'React maintains a virtual DOM — a JS object tree. When state changes, React diffs the virtual DOM with the previous version and only updates changed parts of the real DOM (reconciliation).') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('web-3', 'web-development', 'Advanced', 'A REST API returns 200 OK but with an error message in the body. What is the best practice?', '["This is acceptable — 200 means success","Use 200 for all responses regardless of content","Return the appropriate HTTP status code (4xx/5xx) to reflect the actual error","Always return 500 for server errors"]'::jsonb, 2, 'HTTP status codes communicate the result of a request. Returning 200 with an error body is an anti-pattern that confuses clients and monitoring tools. Use 400 (bad request), 401 (unauthorized), 404 (not found), 500 (server error), etc.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('apt-1', 'aptitude', 'Beginner', 'What is 15% of 200?', '["20","25","30","35"]'::jsonb, 2, '15% of 200 = (15/100) × 200 = 0.15 × 200 = 30. Remember: percentage = part/whole × 100.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('apt-2', 'aptitude', 'Intermediate', 'A train travels 360 km in 4 hours. What is its speed in km/h?', '["80 km/h","90 km/h","100 km/h","120 km/h"]'::jsonb, 1, 'Speed = Distance / Time = 360 km / 4 hours = 90 km/h. This is the basic Speed-Distance-Time formula.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('apt-3', 'aptitude', 'Intermediate', 'If A can do a work in 12 days and B in 18 days, in how many days can they do it together?', '["6 days","7.2 days","8 days","9 days"]'::jsonb, 1, 'A''s rate = 1/12, B''s rate = 1/18. Combined = 1/12 + 1/18 = 3/36 + 2/36 = 5/36. Days = 36/5 = 7.2 days.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('lr-1', 'logical-reasoning', 'Beginner', 'Complete the series: 2, 4, 8, 16, ___', '["24","28","32","36"]'::jsonb, 2, 'Each number is doubled: 2×2=4, 4×2=8, 8×2=16, 16×2=32. This is a geometric sequence with ratio 2.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('lr-2', 'logical-reasoning', 'Intermediate', 'If MANGO is coded as OCPIQ, how is GRAPE coded?', '["ITCQG","ITCRG","IRCQG","ITCQF"]'::jsonb, 0, 'Each letter is shifted +2: M+2=O, A+2=C, N+2=P, G+2=I, O+2=Q. Applying to GRAPE: G+2=I, R+2=T, A+2=C, P+2=R... wait, let''s verify: G→I, R→T, A→C, P→R, E→G = ITCRG.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('cs-1', 'cyber-security', 'Beginner', 'What does SSL/TLS stand for?', '["Secure Server Layer / Transport Layer Security","Secure Sockets Layer / Transport Layer Security","System Security Layer / Transfer Layer Security","Secure Socket Link / Transfer Layered System"]'::jsonb, 1, 'SSL (Secure Sockets Layer) and TLS (Transport Layer Security) are cryptographic protocols designed to provide secure communications over a network. TLS is the successor to SSL.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('cs-2', 'cyber-security', 'Intermediate', 'A website allows users to enter their name in a search field, and the name appears directly in a SQL query. What vulnerability is this?', '["XSS Attack","SQL Injection","CSRF Attack","Buffer Overflow"]'::jsonb, 1, 'SQL Injection occurs when user input is directly embedded in SQL queries without sanitization. An attacker can input SQL code to manipulate the database. Prevention: use parameterized queries/prepared statements.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('cloud-1', 'cloud-computing', 'Beginner', 'What does IaaS stand for in cloud computing?', '["Internet as a Service","Infrastructure as a Service","Integration as a Service","Information as a Service"]'::jsonb, 1, 'IaaS (Infrastructure as a Service) provides virtualized computing resources over the internet — servers, storage, networking. Examples: AWS EC2, Azure VMs, Google Compute Engine.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('cloud-2', 'cloud-computing', 'Intermediate', 'Docker containers are heavier than virtual machines because they include a full operating system.', '["True","False"]'::jsonb, 1, 'Docker containers are lightweight because they share the host OS kernel, unlike VMs that run a complete guest OS. Containers start in seconds, VMs take minutes.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('gk-1', 'general-knowledge', 'Beginner', 'Who is the co-founder of Microsoft?', '["Steve Jobs","Elon Musk","Bill Gates","Jeff Bezos"]'::jsonb, 2, 'Bill Gates co-founded Microsoft in 1975 along with Paul Allen. Microsoft is one of the largest technology companies in the world.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('gk-2', 'general-knowledge', 'Intermediate', 'Which programming language was developed by Google and is used primarily for Android development?', '["Swift","Kotlin","Dart","Go"]'::jsonb, 1, 'Kotlin was developed by JetBrains (not Google) but Google made it the preferred language for Android development in 2017. Dart is used for Flutter, Swift for iOS.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('ca-1', 'career-awareness', 'Beginner', 'What should be the ideal length of a fresher''s resume?', '["3-4 pages","1 page","2-3 pages","As long as needed"]'::jsonb, 1, 'For freshers and early-career professionals, a 1-page resume is ideal. It forces you to highlight only the most relevant information. Experienced professionals (10+ years) may use 2 pages.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('ca-2', 'career-awareness', 'Intermediate', 'During an interview, the interviewer asks "Tell me about yourself." What is the best approach?', '["Recite your entire resume chronologically","Give a 2-minute structured pitch: background → skills → career goals relevant to the role","Talk about your personal life and hobbies in detail","Say \"Everything is on my resume\""]'::jsonb, 1, 'The "Tell me about yourself" question is your elevator pitch. Keep it to 1-2 minutes. Structure: Who you are → relevant skills/experience → why you''re excited about this specific role.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('eng-1', 'english', 'Beginner', 'Choose the correct sentence:', '["She don''t know the answer.","She doesn''t knows the answer.","She doesn''t know the answer.","She not know the answer."]'::jsonb, 2, '"She doesn''t know" is correct. With third-person singular subjects (he, she, it), use "doesn''t" + base verb. "Don''t" is used with I, you, we, they.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('eng-2', 'english', 'Intermediate', 'The synonym of "Eloquent" is ___.', '["Silent","Articulate","Confused","Reluctant"]'::jsonb, 1, '"Eloquent" means fluent and persuasive in speaking or writing. Its synonym is "Articulate" — able to express ideas clearly and effectively.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('math-1', 'mathematics', 'Beginner', 'What is the value of √144?', '["11","12","13","14"]'::jsonb, 1, '√144 = 12, because 12 × 12 = 144. Common perfect squares to remember: 1,4,9,16,25,36,49,64,81,100,121,144.') ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.quiz_questions (question_id, category, difficulty, question, options, correct_answer, explanation) VALUES ('math-2', 'mathematics', 'Intermediate', 'What is the derivative of sin(x)?', '["-cos(x)","cos(x)","-sin(x)","tan(x)"]'::jsonb, 1, 'd/dx[sin(x)] = cos(x). Key derivatives to remember: d/dx[cos(x)] = -sin(x), d/dx[tan(x)] = sec²(x).') ON CONFLICT (question_id) DO NOTHING;
