INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-001', 'AI-Powered Resume Analyzer & Score Predictor', 'ai-ml', 'Intermediate', 'Build a web application that analyzes resumes, scores them against job descriptions using NLP, and provides AI-generated improvement suggestions. Perfect for understanding real-world NLP applications.', '2-3 weeks', '["Python","NLP","Flask","HTML/CSS"]'::jsonb, '[{"step":1,"title":"Setup & Planning","description":"Install libraries, design database schema, plan API structure","estimatedTime":"1 day","resources":["Python docs","spaCy quickstart"]},{"step":2,"title":"PDF Text Extraction","description":"Build PDF parser to extract structured text from resumes","estimatedTime":"2 days","resources":["PyMuPDF docs","pdfplumber tutorial"]},{"step":3,"title":"NLP Processing","description":"Entity recognition, keyword extraction, and skill detection","estimatedTime":"4 days","resources":["spaCy NER tutorial","NLTK guide"]},{"step":4,"title":"Scoring Algorithm","description":"Build cosine similarity-based matching against job descriptions","estimatedTime":"3 days","resources":["scikit-learn TF-IDF","cosine similarity tutorial"]},{"step":5,"title":"Flask API","description":"Build REST API endpoints for upload, analyze, and results","estimatedTime":"2 days","resources":["Flask tutorial","REST API best practices"]},{"step":6,"title":"Frontend","description":"React UI with drag-and-drop upload, score visualization","estimatedTime":"3 days","resources":["React docs","Chart.js tutorial"]},{"step":7,"title":"Deploy","description":"Deploy to Render or Railway with CI/CD pipeline","estimatedTime":"1 day","resources":["Render deployment guide"]}]'::jsonb, 'https://github.com/example/resume-analyzer', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-002', 'Real-Time Stock Market Dashboard with ML Predictions', 'data-science', 'Advanced', 'Build a professional stock market dashboard with live data, technical indicators, and LSTM-based price prediction. Includes backtesting and portfolio simulation.', '4-5 weeks', '["Python","Machine Learning","API Integration","Data Visualization"]'::jsonb, '[{"step":1,"title":"Data Collection","description":"Fetch historical + live stock data using yfinance API","estimatedTime":"2 days","resources":["yfinance documentation","Alpha Vantage API"]},{"step":2,"title":"Data Analysis & EDA","description":"Exploratory analysis, correlation, moving averages, RSI, MACD","estimatedTime":"3 days","resources":["Pandas docs","TA-Lib guide"]},{"step":3,"title":"Feature Engineering","description":"Technical indicators, lag features, sentiment features","estimatedTime":"3 days","resources":["Feature engineering blog","TA-Lib tutorial"]},{"step":4,"title":"ML Model (LSTM)","description":"Build and train LSTM model for price forecasting","estimatedTime":"5 days","resources":["Keras LSTM tutorial","TensorFlow docs"]},{"step":5,"title":"Backtesting","description":"Test prediction strategy against historical data","estimatedTime":"3 days","resources":["Backtrader docs","Zipline tutorial"]},{"step":6,"title":"Dashboard","description":"Streamlit app with interactive Plotly charts","estimatedTime":"4 days","resources":["Streamlit docs","Plotly Express guide"]},{"step":7,"title":"Deploy","description":"Deploy to Streamlit Cloud or Hugging Face Spaces","estimatedTime":"1 day","resources":["Streamlit Cloud guide"]}]'::jsonb, 'https://github.com/example/stock-predictor', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-003', 'E-Commerce Full-Stack Web Application', 'fullstack', 'Intermediate', 'Build a production-ready e-commerce platform with product catalog, cart, checkout with Stripe, user auth, order management, and admin dashboard.', '3-4 weeks', '["React","Node.js","MongoDB","REST APIs","Authentication"]'::jsonb, '[{"step":1,"title":"Project Setup","description":"Next.js frontend + Express backend boilerplate, MongoDB Atlas setup","estimatedTime":"1 day","resources":["Next.js docs","Express.js guide"]},{"step":2,"title":"Authentication","description":"JWT auth, bcrypt password hashing, protected routes","estimatedTime":"3 days","resources":["JWT tutorial","Passport.js docs"]},{"step":3,"title":"Product Catalog","description":"Product listing, search, filter, category, pagination APIs","estimatedTime":"4 days","resources":["MongoDB aggregation tutorial"]},{"step":4,"title":"Cart & Wishlist","description":"Shopping cart state management, wishlist, quantity updates","estimatedTime":"3 days","resources":["Redux Toolkit tutorial","Zustand guide"]},{"step":5,"title":"Checkout & Payments","description":"Stripe integration, order creation, payment confirmation","estimatedTime":"3 days","resources":["Stripe API docs","Webhook guide"]},{"step":6,"title":"Admin Dashboard","description":"Product management, order tracking, analytics dashboard","estimatedTime":"3 days","resources":["Recharts docs","Admin UI patterns"]},{"step":7,"title":"Deploy","description":"Vercel (frontend) + Railway (backend) + MongoDB Atlas","estimatedTime":"2 days","resources":["Vercel deploy guide","Railway docs"]}]'::jsonb, 'https://github.com/example/ecommerce-fullstack', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-004', 'IoT Smart Home Monitoring System', 'iot', 'Intermediate', 'Build a smart home system with temperature, humidity, and motion sensors. Real-time monitoring dashboard, alerts, and historical data visualization.', '3-4 weeks', '["Python","MQTT","Raspberry Pi","React","MongoDB"]'::jsonb, '[{"step":1,"title":"Hardware Setup","description":"Setup Raspberry Pi/Arduino, connect sensors (DHT11, PIR, MQ-2)","estimatedTime":"2 days","resources":["Raspberry Pi docs","Arduino tutorial"]},{"step":2,"title":"Sensor Code","description":"Python scripts to read sensor data on intervals","estimatedTime":"2 days","resources":["GPIO Python tutorial"]},{"step":3,"title":"MQTT Broker","description":"Setup Mosquitto MQTT broker, publish/subscribe sensor topics","estimatedTime":"2 days","resources":["Mosquitto docs","MQTT tutorial"]},{"step":4,"title":"Data Storage","description":"Store time-series data in InfluxDB","estimatedTime":"2 days","resources":["InfluxDB Python tutorial"]},{"step":5,"title":"Alerts","description":"Email/SMS alerts when sensor readings exceed thresholds","estimatedTime":"2 days","resources":["Twilio SMS API","SendGrid"]},{"step":6,"title":"Dashboard","description":"Grafana + custom React dashboard for real-time visualization","estimatedTime":"4 days","resources":["Grafana docs","WebSocket tutorial"]}]'::jsonb, 'https://github.com/example/smart-home-iot', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-005', 'Blockchain-Based Certificate Verification System', 'blockchain', 'Advanced', 'A tamper-proof certificate issuance and verification system on Ethereum. Universities issue certificates as NFTs, employers verify instantly without contacting institutions.', '4-5 weeks', '["Solidity","Ethereum","React","Node.js","Web3.js"]'::jsonb, '[{"step":1,"title":"Blockchain Basics","description":"Learn Ethereum, Solidity, and smart contract fundamentals","estimatedTime":"3 days","resources":["Ethereum docs","CryptoZombies tutorial"]},{"step":2,"title":"Smart Contract","description":"Write and test CertificateNFT.sol with Hardhat","estimatedTime":"5 days","resources":["Hardhat docs","OpenZeppelin contracts"]},{"step":3,"title":"IPFS Storage","description":"Store certificate PDFs on IPFS, get content hash","estimatedTime":"2 days","resources":["IPFS docs","Pinata tutorial"]},{"step":4,"title":"Deploy Contract","description":"Deploy to Goerli testnet, verify on Etherscan","estimatedTime":"1 day","resources":["Hardhat deploy guide"]},{"step":5,"title":"Admin Portal","description":"React app for institutions to issue certificates","estimatedTime":"4 days","resources":["Web3.js tutorial","ethers.js guide"]},{"step":6,"title":"Verification Portal","description":"Public portal for anyone to verify certificate by ID","estimatedTime":"3 days","resources":["React Router docs"]}]'::jsonb, 'https://github.com/example/blockchain-certificates', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-006', 'DevOps CI/CD Pipeline with Kubernetes', 'devops', 'Advanced', 'Build a production-grade CI/CD pipeline that auto-deploys a microservices app to Kubernetes on AWS. Includes blue-green deployments, auto-scaling, and monitoring.', '3-4 weeks', '["Linux","Docker","Kubernetes","Jenkins/GitHub Actions","Terraform"]'::jsonb, '[{"step":1,"title":"Docker Setup","description":"Dockerize a sample microservices application","estimatedTime":"2 days","resources":["Docker docs","Multi-stage builds tutorial"]},{"step":2,"title":"Kubernetes Cluster","description":"Setup AWS EKS cluster with Terraform","estimatedTime":"3 days","resources":["Terraform AWS EKS module","kubectl tutorial"]},{"step":3,"title":"Helm Charts","description":"Create Helm charts for each microservice","estimatedTime":"2 days","resources":["Helm docs","Helm best practices"]},{"step":4,"title":"CI/CD Pipeline","description":"GitHub Actions workflow: test → build → push → deploy","estimatedTime":"4 days","resources":["GitHub Actions docs","Jenkins pipeline guide"]},{"step":5,"title":"Monitoring","description":"Prometheus metrics + Grafana dashboards + alerting","estimatedTime":"3 days","resources":["Prometheus docs","Grafana k8s dashboard"]},{"step":6,"title":"Auto-scaling","description":"HPA, VPA, and Cluster Autoscaler configuration","estimatedTime":"2 days","resources":["Kubernetes HPA docs"]}]'::jsonb, 'https://github.com/example/k8s-cicd-pipeline', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-007', 'Android Health & Fitness Tracker App', 'android', 'Intermediate', 'A beautiful Android fitness app tracking steps, workouts, calories, sleep, and water intake with personalized weekly goals and progress charts.', '3-4 weeks', '["Kotlin","Android Studio","SQLite/Room","Jetpack Compose"]'::jsonb, '[{"step":1,"title":"Project Setup","description":"Android Studio project with Jetpack Compose and Navigation","estimatedTime":"1 day","resources":["Android docs","Compose tutorial"]},{"step":2,"title":"Database Layer","description":"Room database for workouts, meals, and sleep data","estimatedTime":"3 days","resources":["Room docs","MVVM tutorial"]},{"step":3,"title":"Core Features","description":"Step counter, workout log, calorie calculator","estimatedTime":"5 days","resources":["Google Fit API","Sensor API docs"]},{"step":4,"title":"Charts & Analytics","description":"Weekly progress charts with MPAndroidChart","estimatedTime":"3 days","resources":["MPAndroidChart docs"]},{"step":5,"title":"Notifications","description":"Daily reminders, goal alerts with WorkManager","estimatedTime":"2 days","resources":["WorkManager docs","Notification channels"]},{"step":6,"title":"Firebase","description":"Auth, Firestore sync, and Crashlytics","estimatedTime":"3 days","resources":["Firebase Android docs"]}]'::jsonb, 'https://github.com/example/android-fitness-app', NULL) ON CONFLICT (project_id) DO NOTHING;
INSERT INTO public.projects (project_id, title, category, difficulty, description, time_estimate, skills, steps, github_url, demo_url) VALUES ('proj-008', 'Network Vulnerability Scanner', 'cyber-security', 'Advanced', 'Build an ethical network scanner that discovers hosts, scans ports, identifies services, and checks for common CVEs. Generates professional security assessment reports.', '3-4 weeks', '["Python","Networking","Linux","Socket Programming","Web Security"]'::jsonb, '[{"step":1,"title":"Networking Fundamentals","description":"TCP/IP, ports, protocols, OSI model review","estimatedTime":"2 days","resources":["Networking fundamentals course"]},{"step":2,"title":"Host Discovery","description":"ARP scan, ICMP ping sweep with Scapy","estimatedTime":"2 days","resources":["Scapy docs","Python socket tutorial"]},{"step":3,"title":"Port Scanner","description":"TCP/UDP port scanner with banner grabbing","estimatedTime":"3 days","resources":["Nmap scripting tutorial"]},{"step":4,"title":"Vulnerability Check","description":"CVE database lookup for identified services","estimatedTime":"4 days","resources":["NVD API docs","CVE database tutorial"]},{"step":5,"title":"Report Generator","description":"HTML/PDF security assessment reports","estimatedTime":"2 days","resources":["ReportLab docs","Jinja2 template"]},{"step":6,"title":"Web Dashboard","description":"Flask + React UI for running scans and viewing reports","estimatedTime":"4 days","resources":["Flask docs","React tutorial"]}]'::jsonb, 'https://github.com/example/vuln-scanner', NULL) ON CONFLICT (project_id) DO NOTHING;
